/* Topic-first, manually selected course references and existing licensed collections. */
let aSkills=null,aCollection=null,aCollectionPage=0,aExtraLoaded=false,aCollectionUnit='all';
async function aExtraCourses(){if(aExtraLoaded)return;const rows=await aFetch('./data/skill_courses.json');for(const c of rows)if(!courses.some(x=>x.id===c.id))courses.push(c);aExtraLoaded=true}
async function aLoadSkills(){await aExtraCourses();if(!aSkills)aSkills=await aFetch('./data/skill_catalog.json');if(!currCatalogue)currCatalogue=await aFetch('./data/curriculum/index.json');return aSkills}
// Pages de la bibliothèque (compétences, thèmes, collections, tous les cours) : runtime/library-views.js, chargé à la demande et précaché par le service worker.
let aLib=null,aLibPromise=null;
function aLibLoad(){return aLibPromise||(aLibPromise=import(new URL('./runtime/library-views.js',document.baseURI).href).then(m=>{aLib=m.init({skills:()=>aSkills,programmes:()=>currCatalogue,collection:()=>aCollection,collectionPage:()=>aCollectionPage,collectionUnit:()=>aCollectionUnit,courses:()=>courses,resourceCard:r=>resourceCard(r),esc,at,aLink,aPageHead,icon,getCourse,aPythonCourseCard,aLabel})}).catch(e=>{aLibPromise=null;throw e}))}
const aLibWait=()=>`<p role="status">${esc(at('load'))}</p>`;
function aSkillHub(){return aLib?aLib.hub():aLibWait()}
function aSkillTopic(id){return aLib?aLib.topic(id):aLibWait()}
function aCollectionView(){return aLib?aLib.collection():aLibWait()}
const aResolveBeforeSkills=aResolve;aResolve=async function(){const hash=location.hash,route=academyRoute(hash);aRoute=route;aError=false;aLoading=true;render();try{if(['path','step'].includes(route.kind)&&['cours-cv-candidatures','cours-entretien-professionnel','cours-documents-pratique','cours-tableurs-pratique'].includes(route.id))await aExtraCourses();if(['bibliotheque','collection'].includes(route.kind)){await aLoadSkills();aCollectionPage=0;if(route.kind==='collection'){aCollection=await aFetch('./data/collections/'+encodeURIComponent(route.id)+'.json');const parts=hash.split('/'),index=parts[3]==='unite'?Number(parts[4]):-1;aCollectionUnit=aCollection.course.units?.[index]||'all'};await aLibLoad().catch(e=>{if(route.kind==='collection'||route.id)throw e})}}catch{if(location.hash===hash){aLoading=false;aError=true;render()}return}if(location.hash!==hash)return;return aResolveBeforeSkills()};
const aLibraryBeforeSkills=aLibrary;aLibrary=function(){if(aRoute.id==='competences')return aSkillHub();if(aRoute.id==='theme')return aSkillTopic(aRoute.careerId);if(aRoute.id==='cours')return aLib?aLib.all():aLibWait();const html=aLibraryBeforeSkills();if(!aLib||!aSkills||aQuery.trim()||aFormat!=='all'||aSubject!=='all')return html;return aLib.decorate(html)};
const aViewBeforeSkills=aView;aView=function(){if(aRoute.kind==='collection')return aCollectionView();return aViewBeforeSkills()};
document.addEventListener('click',e=>{const b=e.target.closest('[data-collection-page],[data-collection-video],[data-search-page]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.dataset.searchPage){aSearchPage=Math.max(0,aSearchPage+(b.dataset.searchPage==='next'?1:-1));render();$('#main').scrollIntoView({block:'start'});return}if(b.dataset.collectionPage){aCollectionPage=Math.max(0,aCollectionPage+(b.dataset.collectionPage==='next'?1:-1));render();$('#main').scrollIntoView({block:'start'});return}if(b.dataset.collectionVideo&&/^[\w-]{11}$/.test(b.dataset.collectionVideo))$('#a-collection-player').innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${b.dataset.collectionVideo}?rel=0&hl=fr&playsinline=1" title="${esc(aCollection.course.title_fr)}" allow="encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`},true);

document.addEventListener('change',event=>{if(event.target.id==='collection-unit')aGo('#/collection/'+aCollection.course.id+(event.target.value==='all'?'':'/unite/'+event.target.value))});
